package com.abhishek.hotelbooking.controller; import com.abhishek.hotelbooking.dto.room.RoomRequest; import com.abhishek.hotelbooking.entity.Room; import com.abhishek.hotelbooking.service.impl.RoomService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.*;
@RestController @RequestMapping("/api/hotels/{hotelId}/rooms") public class RoomController { private final RoomService service; public RoomController(RoomService service){this.service=service;} @GetMapping public List<Room> rooms(@PathVariable Long hotelId){return service.byHotel(hotelId);} @GetMapping("/available") public List<Room> available(@PathVariable Long hotelId,@RequestParam LocalDate checkIn,@RequestParam LocalDate checkOut){return service.available(hotelId,checkIn,checkOut);} @PreAuthorize("hasRole('ADMIN')") @PostMapping public Room create(@PathVariable Long hotelId,@Valid @RequestBody RoomRequest r){return service.create(hotelId,r);} }